Voici un exemple de code pour créer un bot Discord avec la commande "bannir" à l'aide de Discord.js v14 :

```javascript
const { Client, GatewayIntentBits } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.on('ready', () => {
  console.log(`Bot ${client.user.tag} est prêt!`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'bannir') {
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Vous n'avez pas la permission de bannir des utilisateurs.', ephemeral: true });
    }

    const user = interaction.options.getUser('utilisateur');

    try {
      await interaction.guild.members.ban(user.id);
      return interaction.reply({ content: `L'utilisateur ${user.tag} a été banni.` });
    } catch (error) {
      console.error(error);
      return interaction.reply({ content: 'Une erreur est survenue lors du bannissement de l'utilisateur.', ephemeral: true });
    }
  }
});

client.login(process.env.TOKEN);
```

Remarquez que vous devez remplacer `process.env.TOKEN` par votre propre clé de bot Discord avant de lancer le bot. Cette commande utilise les intentions `Guilds`, `GuildMessages`, et `MessageContent` pour que le bot puisse interagir avec les messages de serveur et les utilisateurs. La commande "bannir" est une commande slash qui prend en argument l'utilisateur à bannir. Si l'utilisateur n'a pas la permission de bannir, il recevra un message privé. Si une erreur se produit lors du bannissement, le bot enverra également un message privé.

