Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <string>
#include <iostream>
#include <regex>

std::string convertMarkdownToHTML(std::string& markdown) {
    std::string html;

    // Titres
    std::regex title_regex("^#+(\\s+)?(.*?)(\\s+)?#", std::regex::icase);
    std::smatch title_match;

    while (std::regex_search(markdown, title_match, title_regex)) {
        std::string level = title_match[1].str();
        std::string text = title_match[2].str();
        std::string spacing = title_match[3].str();

        std::string html_title = "<h" + level + spacing + ">" + text + "</h" + level + ">\n";
        markdown.replace(title_match.position(), title_match.length(), html_title);
    }

    // Gras et italique
    std::regex bold_italic_regex("\\*\\*([^\\*]*)\\*\\*|__([^\\_]+)__");
    std::regex bold_regex("\\*([^\\*]*)\\*|__([^\\_]+)__");
    std::regex italic_regex("\\*([^\\*]*)\\*|_([^_]+)_");

    while (std::regex_search(markdown, title_match, bold_italic_regex)) {
        std::string type = title_match[1].str();
        std::string text = title_match[2].str();

        if (type == "**") {
            html += "<strong>" + text + "</strong>";
        } else {
            html += "<em>" + text + "</em>";
        }

        markdown.replace(title_match.position(), title_match.length(), text);
    }

    while (std::regex_search(markdown, title_match, bold_regex)) {
        std::string type = title_match[1].str();
        std::string text = title_match[2].str();

        if (type == "*") {
            html += "<strong>" + text + "</strong>";
        } else {
            html += "<strong>" + text + "</strong>";
        }

        markdown.replace(title_match.position(), title_match.length(), text);
    }

    while (std::regex_search(markdown, title_match, italic_regex)) {
        std::string type = title_match[1].str();
        std::string text = title_match[2].str();

        if (type == "*") {
            html += "<em>" + text + "</em>";
        } else {
            html += "<em>" + text + "</em>";
        }

        markdown.replace(title_match.position(), title_match.length(), text);
    }

    // Lien
    std::regex link_regex("\\[(.+?)\\]\\((.+?)\\)");
    std::smatch link_match;

    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string text = link_match[1].str();
        std::string href = link_match[2].str();

        html += "<a href='" + href + "'>" + text + "</a>";
        markdown.replace(link_match.position(), link_match.length(), text);
    }

    // Retour à la ligne
    std::regex newline_regex("(\\n)+");
    std::string newlines = std::regex_replace(markdown, newline_regex, "<br />");

    html += newlines;

    return html;
}
```

Cette fonction utilise des expressions régulières pour détecter les différents éléments de Markdown et les convertir en HTML. Elle renvoie le texte HTML converti dans une nouvelle chaîne de caractères. Notez que cette fonction ne traite que les éléments de base de Markdown, mais il est possible d'en ajouter d'autres en fonction de vos besoins.

