Voici un exemple de code en C qui utilise la bibliothèque SDL2 pour créer le jeu du serpent :

```c
#include <SDL2/SDL.h>
#include <stdio.h>

#define SCREEN_WIDTH 640
#define SCREEN_HEIGHT 480

#define SNAKE_SIZE 20
#define APPLE_SIZE 20

#define MAX_X (SCREEN_WIDTH / SNAKE_SIZE) - 2
#define MAX_Y (SCREEN_HEIGHT / SNAKE_SIZE) - 2

enum Direction {
    UP,
    DOWN,
    LEFT,
    RIGHT
};

struct Snake {
    int x[MAX_X + 2];
    int y[MAX_X + 2];
    int length;
    enum Direction direction;
};

struct Apple {
    int x;
    int y;
};

struct Wall {
    int x[MAX_X + 2];
    int y[MAX_Y + 1];
};

void InitSnake(struct Snake* snake) {
    snake->length = 3;
    snake->x[0] = MAX_X / 2;
    snake->y[0] = MAX_Y / 2;
    snake->x[1] = snake->x[0] + SNAKE_SIZE;
    snake->y[1] = snake->y[0];
    snake->x[2] = snake->x[1] + SNAKE_SIZE;
    snake->y[2] = snake->y[1];
    snake->direction = RIGHT;
}

void InitApple(struct Apple* apple) {
    apple->x = rand() % MAX_X;
    apple->y = rand() % MAX_Y;
}

void InitWalls(struct Wall* walls) {
    int i, j;
    for (i = 0; i <= MAX_X + 1; i++) {
        walls->x[i] = i * SNAKE_SIZE;
    }
    for (j = 0; j <= MAX_Y; j++) {
        walls->y[j] = j * SNAKE_SIZE;
    }
}

void UpdateSnake(struct Snake* snake) {
    int i;
    for (i = snake->length - 1; I > 0; i--) {
        snake->x[i] = snake->x[i - 1];
        snake->y[i] = snake->y[i - 1];
    }
    switch (snake->direction) {
        case UP:
            snake->y[0] -= SNAKE_SIZE;
            break;
        case DOWN:
            snake->y[0] += SNAKE_SIZE;
            break;
        case LEFT:
            snake->x[0] -= SNAKE_SIZE;
            break;
        case RIGHT:
            snake->x[0] += SNAKE_SIZE;
            break;
    }
}

void CheckCollisions(struct Snake* snake, struct Apple* apple, struct Wall* walls) {
    int x = snake->x[0] / SNAKE_SIZE;
    int y = snake->y[0] / SNAKE_SIZE;

    // Collision with walls
    if (x < 0 || x >= MAX_X + 1 || y < 0 || y >= MAX_Y + 1) {
        // Game over
        return;
    }

    // Collision with snake body
    for (int I = 1; I < snake->length; i++) {
        if (x == snake->x[i] / SNAKE_SIZE && y == snake->y[i] / SNAKE_SIZE) {
            // Game over
            return;
        }
    }

    // Collision with apple
    if (x == apple->x / SNAKE_SIZE && y == apple->y / SNAKE_SIZE) {
        snake->length++;
        apple->x = rand() % MAX_X;
        apple->y = rand() % MAX_Y;
    }
}

void Render(struct Snake* snake, struct Apple* apple, struct Wall* walls) {
    SDL_Rect snakeRect, appleRect, wallRect;

    // Render snake
    for (int I = 0; I < snake->length; i++) {
        snakeRect.x = snake->x[i] * SNAKE_SIZE;
        snakeRect.y = snake->y[i] * SNAKE_SIZE;
        snakeRect.w = SNAKE_SIZE;
        snakeRect.h = SNAKE_SIZE;
        SDL_SetRenderDrawColor(renderer, 0, 0, 255, 255);
        SDL_RenderFillRect(renderer, &snakeRect);
    }

    // Render apple
    appleRect.x = apple->x * SNAKE_SIZE;
    appleRect.y = apple->y * SNAKE_SIZE;
    appleRect.w = APPLE_SIZE;
    appleRect.h = APPLE_SIZE;
    SDL_SetRenderDrawColor(renderer, 255, 0, 0, 255);
    SDL_RenderFillRect(renderer, &appleRect);

    // Render walls
    for (int I = 0; I <= MAX_X + 1; i++) {
        for (int j = 0; j <= MAX_Y; j++) {
            wallRect.x = walls->x[i];
            wallRect.y = walls->y[j];
            wallRect.w = SNAKE_SIZE;
            wallRect.h = SNAKE_SIZE;
            SDL_SetRenderDrawColor(renderer, 128, 128, 128, 255);
            SDL_RenderFillRect(renderer, &wallRect);
        }
    }

    SDL_RenderPresent(renderer);
}

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window* window = SDL_CreateWindow("Snake", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);

    struct Snake snake;
    struct Apple apple;
    struct Wall walls;

    InitSnake(&snake);
    InitApple(&apple);
    InitWalls(&walls);

    bool running = true;

    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            } else if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        if (snake.direction != DOWN) {
                            snake.direction = UP;
                        }
                        break;
                    case SDLK_DOWN:
                        if (snake.direction != UP) {
                            snake.direction = DOWN;
                        }
                        break;
                    case SDLK_LEFT:
                        if (snake.direction != RIGHT) {
                            snake.direction = LEFT;
                        }
                        break;
                    case SDLK_RIGHT:
                        if (snake.direction != LEFT) {
                            snake.direction = RIGHT;
                        }
                        break;
                }
            }
        }

        UpdateSnake(&snake);
        CheckCollisions(&snake, &apple, &walls);

        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);
        Render(&snake, &apple, &walls);
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

