```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string mot_a_chercher;
    int compteur = 0;

    // Demander à l'utilisateur d'entrer le mot à chercher et le nom du fichier à lire
    cout << "Entrez le mot à chercher : ";
    cin >> mot_a_chercher;
    cout << "Entrez le nom du fichier à lire : ";
    string nom_fichier;
    cin >> nom_fichier;

    // Ouvrir le fichier pour lecture
    ifstream fichier(nom_fichier);
    if (!fichier.is_open()) {
        cout << "Erreur : impossible d'ouvrir le fichier " << nom_fichier << endl;
        return 1;
    }

    // Lire le fichier ligne par ligne et compter le nombre d'occurrences du mot spécifique
    string ligne;
    while (getline(fichier, ligne)) {
        size_t position = 0;
        while ((position = ligne.find(mot_a_chercher, position)) != string::npos) {
            compteur++;
            position += mot_a_chercher.length();
        }
    }

    // Afficher le résultat
    cout << "Le mot \"" << mot_a_chercher << "\" apparait " << compteur << " fois dans le fichier " << nom_fichier << endl;

    // Fermer le fichier
